                background:#c84f24;
                margin-top:10px;
                border-radius:20px;">
            </div>
        </div>

        <!-- Security Notice -->
        <div style="
            background:#faf6f3;
            border-left:5px solid #c84f24;
            border-radius:10px;
            padding:18px;
            margin:25px 0;">

            <p style="
                margin:0;
                color:#4d240f;
                font-size:15px;
                line-height:1.8;">

                 <strong>HomeBite will never call or message you for this code.</strong>
                If you didn't request this login, simply ignore this email.
                Your account remains secure.
            </p>
        </div>

        <hr style="border:none;
                   border-top:1px solid #e5e7eb;
                   margin:35px 0;">

        <p style="
            color:#6b7280;
            font-size:16px;
            margin-bottom:10px;">
            Hungry for home? We've got you covered. 
